  const token=dragReady,origin=filePress?.id===id?filePress.point:toWorld(e.clientX,e.clientY),moving=expandedSelection();
  fileDrag={token,boardId:board.id,origin,moving,origins:new Map([...moving].map(key=>[key,{x:board.items[key].x,y:board.items[key].y}]))};
