 function endFileDrag(token,error){if(!fileDrag||fileDrag.token!==token)return;const d=fileDrag;fileDrag=null;restoreFilePreview(d);dragging=false;filePress=null;stage.classList.remove('is-file-dragging');applyPending();positionPorts();if(!error)prepareExport();}
 function previewFileDrag(e){if(!fileDrag||board.id!==fileDrag.boardId)return;const point=toWorld(e.clientX,e.clientY),dx=point.x-fileDrag.origin.x,dy=point.y-fileDrag.origin.y;for(const [id,start] of fileDrag.origins){const row=board.items[id];if(!row)continue;row.x=Math.max(-100000,Math.min(100000,start.x+dx));row.y=Math.max(-100000,Math.min(100000,start.y+dy));if(nodes.has(id))updateNode(nodes.get(id),row);}highlightDrop(fileDrag.moving);renderLinks();}
 stage.addEventListener('dragover',e=>{if(!fileDrag)return;e.preventDefault();e.stopPropagation();if(e.dataTransfer)e.dataTransfer.dropEffect='copy';previewFileDrag(e);});
