 stage.addEventListener('drop',e=>{if(!fileDrag)return;e.preventDefault();e.stopPropagation();previewFileDrag(e);const d=fileDrag,changes=[...d.moving].map(id=>({id,x:board.items[id].x,y:board.items[id].y}));fileDrag=null;filePress=null;stage.classList.remove('is-file-dragging');clearDropHighlight();run(async()=>{try{await action('move',changes);}catch(error){restoreFilePreview(d);throw error;}finally{dragging=false;applyPending();positionPorts();prepareExport();}});});
 const observer=new IntersectionObserver(entries=>{for(const entry of entries){const node=entry.target;node.dataset.inView=String(entry.isIntersecting);const image=node.querySelector('.canvas-picture img');if(entry.isIntersecting&&image?.dataset.url&&image.src!==image.dataset.url)image.src=image.dataset.url;}},{root:stage,rootMargin:'150px'});
 function populate(list){$('canvasProject').replaceChildren(...(list.boards.length?list.boards.map(b=>new Option(b.name,b.id)):[new Option('选择项目路径','')]));$('canvasProject').value=board?.id||list.active||'';}
 async function show(value){active=value;root.hidden=!value;document.body.classList.toggle('canvas-mode',value);canvasTab.setAttribute('aria-selected',String(value));libraryTab.setAttribute('aria-selected',String(!value));await api.command('workspace',value?'canvas':'library');if(!value){cancelGestures();await flushView();return;}if(!loaded){const list=await api.command('list');populate(list);if(list.active)await activate(list.active);loaded=true;if(list.warning)message(list.warning,true);}stage.focus();}
