 async function useBoard(next){for(const n of nodes.values()){observer.unobserve(n);interact(n).unset();n.remove();}nodes.clear();selected.clear();inboxSelected.clear();board=next;pending=null;closeMenu();$('canvasPath').value=board.root;populate(await api.command('list'));
  for(const [id,key] of [['canvasSearch','search'],['canvasFilter','status']])$(id).value=key==='status'?'':board.filters[key]||'';
  cancelGestures();const v=board.viewport;world.style.setProperty('--canvas-scale',v.scale);if(pz)pz.destroy();pz=Panzoom(world,{origin:'0 0',minScale:.05,maxScale:5,step:.15,excludeClass:'panzoom-exclude',noBind:true,canvas:true,cursor:'default',startScale:v.scale,startX:v.x,startY:v.y});
  render();$('canvasShot').value=board.filters.shot||'';render();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));pz.zoom(v.scale,{silent:true});pz.pan(v.x,v.y,{silent:true,force:true});$('canvasZoom').textContent=Math.round(v.scale*100)+'%';
  if(v.scale===1&&v.x===0&&v.y===0){const first=board.groups.K00?'K00':Object.keys(board.groups)[0];if(first){$('canvasShot').value=first;render();fit();await saveFilters();}}
  await flushView();message(board.warning||'已恢复项目 · 新素材按导入设置加入',!!board.warning);
 }
 async function flushView(){clearTimeout(viewTimer);if(board&&pz){const v={...pz.getPan(),scale:pz.getScale()};board.viewport=v;await api.command('viewport',board.id,v);}}
 world.addEventListener('panzoomchange',e=>{if(!board||loading)return;board.viewport={x:e.detail.x,y:e.detail.y,scale:e.detail.scale};$('canvasZoom').textContent=Math.round(e.detail.scale*100)+'%';world.style.setProperty('--canvas-scale',e.detail.scale);positionPorts();if(connection)drawConnection();clearTimeout(viewTimer);viewTimer=setTimeout(()=>run(flushView),250);});
