  for(const i of rows){const row=el('label','canvas-inbox-row'),check=el('input');check.type='checkbox';check.checked=inboxSelected.has(i.id);check.setAttribute('aria-label','选择 '+i.name);check.onchange=()=>{check.checked?inboxSelected.add(i.id):inboxSelected.delete(i.id);updateAdmit();};const img=el('img');img.loading='lazy';img.alt='';img.src=url(i);img.onerror=()=>img.hidden=true;const info=el('span');info.append(el('strong','',i.name),el('small','',i.admitted?(i.hiddenAt?'已隐藏':'已在画布'):i.relative));row.append(check,img,info);list.append(row);}
