 function updateAdmit(){$('canvasAdmit').textContent=inboxSelected.size?`加入 ${inboxSelected.size} 项`:'加入画布';$('canvasAdmit').disabled=!inboxSelected.size;}
 function nodeDepth(i){let n=0,p=i.parentId;while(p&&n<32){n++;p=board.items[p]?.parentId;}return n;}
 function updateNode(n,i){for(const k of ['x','y','width','height'])n.style[{x:'left',y:'top'}[k]||k]=geometry.box(i)[k]+'px';n.style.setProperty('--node-color',i.color||'#b78c66');n.style.zIndex=i.kind==='group'?String(1+nodeDepth(i)):String(40+nodeDepth(i));n.classList.toggle('selected',selected.has(i.id));n.classList.toggle('confirmed',i.status==='confirmed');n.classList.toggle('missing',!!i.missing);n.setAttribute('aria-label',i.name);
  n.classList.toggle('folded',i.kind==='group'&&!!i.collapsed);const fold=n.querySelector('.canvas-fold');if(fold){fold.setAttribute('aria-label',i.collapsed?'展开分组':'折叠分组');fold.title=i.collapsed?'展开分组':'折叠分组';fold.replaceChildren(icon(i.collapsed?'expand':'collapse'));}const name=n.querySelector('.canvas-node-name');if(name)name.textContent=i.name;const text=n.querySelector('.canvas-note-body');if(text)text.textContent=i.text||'双击添加说明';
  const caption=n.querySelector('.canvas-caption');if(caption){caption.querySelector('strong').textContent=i.name;caption.querySelector('small').textContent=i.missing?'原文件缺失':i.pixelWidth?`${i.pixelWidth} × ${i.pixelHeight}`:'';n.style.setProperty('--caption-height',Math.min(22,i.height/6)+'px');n.style.setProperty('--caption-font',Math.min(11,i.height/12)+'px');}
  const image=n.querySelector('.canvas-picture img');if(image){const src=url(i);if(image.dataset.url!==src){image.dataset.url=src;image.hidden=false;if(n.dataset.inView==='true')image.src=src;}}
  const seq=n.querySelector('.canvas-sequence-label');if(seq)seq.textContent=`▶ ${i.frameIds.length} 帧 · ${i.fps} fps${i.gaps?' · 缺帧':''}`;
 }
