 function expandedSelection(){const ids=new Set(selected);let changed=true;while(changed){changed=false;for(const i of Object.values(board.items))if(i.parentId&&ids.has(i.parentId)&&!ids.has(i.id)){ids.add(i.id);changed=true;}}return ids;}
