 function visibleEndpoint(id){let i=board.items[id],result=nodes.has(id)?id:null,n=0;while(i?.parentId&&n++<40){i=board.items[i.parentId];if(i?.collapsed&&nodes.has(i.id))result=i.id;}return result;}
